tests:
test({ sr: 'vraća grad kad postoji', en: 'returns the city when it exists' }, () => {
  expect(getCity({ address: { city: 'Novi Sad' } })).toBe('Novi Sad');
});
test({ sr: 'bez adrese vraća Unknown', en: 'without an address returns Unknown' }, () => {
  expect(getCity({})).toBe('Unknown');
});
test({ sr: 'adresa bez grada vraća Unknown', en: 'an address without a city returns Unknown' }, () => {
  expect(getCity({ address: {} })).toBe('Unknown');
});

hiddenTests:
test('address null gives Unknown', () => {
  expect(getCity({ address: null })).toBe('Unknown');
});
test('address undefined gives Unknown', () => {
  expect(getCity({ address: undefined })).toBe('Unknown');
});
test('city null gives Unknown', () => {
  expect(getCity({ address: { city: null } })).toBe('Unknown');
});
test('an empty text is a valid city', () => {
  expect(getCity({ address: { city: '' } })).toBe('');
});
test('other properties do not matter', () => {
  expect(getCity({ name: 'Ana', address: { street: 'Main 1', city: 'Nis' } })).toBe('Nis');
  expect(getCity({ name: 'Ana', address: { street: 'Main 1' } })).toBe('Unknown');
});
test('never throws', () => {
  expect(() => getCity({})).not.toThrow();
  expect(() => getCity({ address: null })).not.toThrow();
});

solutions.code:
function getCity(user) {
  const address = user.address;
  if (address === undefined || address === null) return 'Unknown';
  const city = address.city;
  if (city === undefined || city === null) return 'Unknown';
  return city;
}
